<?php require __DIR__.'/../inc/bootstrap.php'; require_admin(); $posts=load_json('posts.json',[]); if(isset($_GET['delete'])){ $id=(string)$_GET['delete']; $posts=array_values(array_filter($posts,fn($p)=>(string)$p['id']!==$id)); save_json('posts.json',$posts); header('Location: posts.php');exit;} ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>POSTS</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container"><div class="card"><h1>[ LOG MANAGEMENT ]</h1><p><a href="post_edit.php">+ NEW LOG</a> | <a href="index.php">BACK</a></p><?php foreach(array_reverse($posts) as $p): ?><article class="card"><div class="post-title"><?=e($p['title'])?></div><div class="post-meta"><?=e($p['date']??'')?></div><a href="post_edit.php?id=<?=urlencode($p['id'])?>">EDIT</a> | <a href="?delete=<?=urlencode($p['id'])?>" onclick="return confirm('Delete this log?')">DELETE</a></article><?php endforeach; ?></div></main></body></html>
